import java.io.File;
import java.io.IOException;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

public class OperacionesFile {
    public static void main(String[] args) throws IOException {
        // === CREAR FICHERO ===
        File fichero = new File("ejemplo.txt");

        if (!fichero.exists()) {
            boolean creado = fichero.createNewFile();
            System.out.println("Fichero creado: " + creado);
        } else {
            System.out.println("El fichero ya existe");
        }

        // === INFORMACION DEL FICHERO ===
        System.out.println("\n=== Informacion ===");
        System.out.println("Nombre: " + fichero.getName());
        System.out.println("Ruta: " + fichero.getPath());
        System.out.println("Ruta absoluta: " + fichero.getAbsolutePath());
        System.out.println("Directorio padre: " + fichero.getParent());
        System.out.println("Tamano: " + fichero.length() + " bytes");
        System.out.println("Es fichero: " + fichero.isFile());
        System.out.println("Es directorio: " + fichero.isDirectory());
        System.out.println("Se puede leer: " + fichero.canRead());
        System.out.println("Se puede escribir: " + fichero.canWrite());

        // Ultima modificacion formateada
        LocalDateTime fecha = LocalDateTime.ofInstant(
            Instant.ofEpochMilli(fichero.lastModified()), ZoneId.systemDefault());
        System.out.println("Ultima modificacion: " +
            fecha.format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss")));

        // === CREAR DIRECTORIOS ===
        File directorio = new File("cursos/programacion/ejercicios");
        if (!directorio.exists()) {
            boolean creado = directorio.mkdirs(); // Crea todos los padres
            System.out.println("\nDirectorio creado: " + creado);
        }

        // === LISTAR CONTENIDO ===
        File raiz = new File(".");
        System.out.println("\n=== Contenido del directorio actual ===");
        String[] archivos = raiz.list();
        if (archivos != null) {
            for (String nombre : archivos) {
                File f = new File(raiz, nombre);
                String tipo = f.isDirectory() ? "[DIR]" : "[FIC]";
                System.out.printf("%s %s (%d bytes)%n", tipo, nombre, f.length());
            }
        }

        // === ELIMINAR ===
        if (fichero.exists()) {
            boolean eliminado = fichero.delete();
            System.out.println("\nFichero eliminado: " + eliminado);
        }
    }
}

import java.io.File;

public class ExplorarDirectorio {

    public static void explorar(File directorio, String indentacion) {
        if (!directorio.exists() || !directorio.isDirectory()) return;

        File[] archivos = directorio.listFiles();
        if (archivos == null) return;

        for (File archivo : archivos) {
            if (archivo.isDirectory()) {
                System.out.println(indentacion + "📁 " + archivo.getName());
                explorar(archivo, indentacion + "  ");
            } else {
                System.out.printf(indentacion + "📄 %s (%d bytes)%n",
                    archivo.getName(), archivo.length());
            }
        }
    }

    public static void main(String[] args) {
        File directorio = new File(".");
        System.out.println("Estructura de archivos:");
        explorar(directorio, "  ");
    }
}

