import java.io.*;

public class LeerBufferedReader {
    public static void main(String[] args) {
        // Crear un fichero de ejemplo
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("alumnos.txt"))) {
            writer.write("Ana,8.5"); writer.newLine();
            writer.write("Carlos,7.0"); writer.newLine();
            writer.write("Maria,9.2"); writer.newLine();
            writer.write("Pedro,5.5"); writer.newLine();
        } catch (IOException e) {
            System.out.println("Error creando fichero: " + e.getMessage());
            return;
        }

        // Leer linea a linea
        try (BufferedReader reader = new BufferedReader(new FileReader("alumnos.txt"))) {
            String linea;
            int numLinea = 1;
            while ((linea = reader.readLine()) != null) {
                System.out.printf("Linea %d: %s%n", numLinea, linea);
                numLinea++;
            }
        } catch (FileNotFoundException e) {
            System.out.println("Fichero no encontrado: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Error de lectura: " + e.getMessage());
        }
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class LeerConFiles {
    public static void main(String[] args) {
        Path fichero = Path.of("alumnos.txt");

        // === readString(): todo el fichero en un String ===
        try {
            String contenido = Files.readString(fichero);
            System.out.println("=== Contenido completo ===");
            System.out.println(contenido);
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // === readAllLines(): todas las lineas en una List ===
        try {
            List<String> lineas = Files.readAllLines(fichero);
            System.out.println("=== Lineas ===");
            for (String linea : lineas) {
                System.out.println("  " + linea);
            }
            System.out.println("Total lineas: " + lineas.size());
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // === readString() con Path (Java 11+) ===
        try {
            String contenido = Files.readString(Path.of("alumnos.txt"));
            System.out.println("\n=== Contenido ===");
            System.out.println(contenido);
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class LeerNotas {

    record RegistroNota(String nombre, double nota) {}

    public static List<RegistroNota> leerFicheroNotas(String ruta) {
        List<RegistroNota> registros = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(ruta))) {
            String linea;
            int numLinea = 1;

            while ((linea = reader.readLine()) != null) {
                // Saltar lineas vacias o comentarios
                linea = linea.trim();
                if (linea.isEmpty() || linea.startsWith("#")) {
                    numLinea++;
                    continue;
                }

                // Parsear: nombre,nota
                String[] partes = linea.split(",");
                if (partes.length == 2) {
                    String nombre = partes[0].trim();
                    double nota = Double.parseDouble(partes[1].trim());
                    registros.add(new RegistroNota(nombre, nota));
                } else {
                    System.out.printf("Linea %d formato incorrecto: %s%n", numLinea, linea);
                }
                numLinea++;
            }
        } catch (FileNotFoundException e) {
            System.out.println("Fichero no encontrado: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Error de lectura: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.out.println("Error de formato numerico: " + e.getMessage());
        }

        return registros;
    }

    public static void main(String[] args) {
        List<RegistroNota> notas = leerFicheroNotas("alumnos.txt");
        System.out.println("Registros leidos: " + notas.size());
        for (RegistroNota r : notas) {
            System.out.printf("  %s: %.1f%n", r.nombre(), r.nota());
        }
    }
}

