import java.io.*;
import java.util.*;

public class ProcesadorLogs {
    record LogEntry(String fecha, String accion, String detalle) {}

    public static void main(String[] args) {
        List<LogEntry> entradas = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader("logs.txt"))) {
            String linea;
            while ((linea = reader.readLine()) != null) {
                // Parsear: [2026-09-15 10:30] MATRICULA: Ana → Prog
                if (linea.startsWith("[")) {
                    int cierre = linea.indexOf(']');
                    if (cierre > 0) {
                        String fecha = linea.substring(1, cierre);
                        String resto = linea.substring(cierre + 2).trim();
                        int dosPuntos = resto.indexOf(':');
                        if (dosPuntos > 0) {
                            String accion = resto.substring(0, dosPuntos).trim();
                            String detalle = resto.substring(dosPuntos + 1).trim();
                            entradas.add(new LogEntry(fecha, accion, detalle));
                        }
                    }
                }
            }
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        System.out.println("Total entradas: " + entradas.size());

        // Contar por tipo
        Map<String, Long> porTipo = entradas.stream()
            .collect(java.util.stream.Collectors.groupingBy(
                LogEntry::accion, java.util.stream.Collectors.counting()));
        porTipo.forEach((k, v) -> System.out.println(k + ": " + v));
    }
}

