        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // === Añadir contenido (Java 11+) ===
        try {
            Files.writeString(Path.of("log.txt"), "Inicio de sesion\n");
            Files.writeString(Path.of("log.txt"), "Alumno creado\n");
            // Por defecto sobrescribe. Para append:
            Files.write(
                Path.of("log.txt"),
                List.of("Nota asignada"),
                java.nio.file.StandardOpenOption.CREATE,
                java.nio.file.StandardOpenOption.APPEND
            );
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.List;

public class GenerarInforme {

    public static void generarInforme(List<Alumno> alumnos, String ruta) {
        try (PrintWriter pw = new PrintWriter(new BufferedWriter(new FileWriter(ruta)))) {
            pw.println("=".repeat(50));
            pw.println("         INFORME ACADEMICO");
            pw.println("         Programacion - Curso 2026/2027");
            pw.println("=".repeat(50));
            pw.println();

            // Cabecera
            pw.printf("%-20s %8s %10s%n", "Alumno", "Notas", "Media");
            pw.printf("%-20s %8s %10s%n", "-".repeat(20), "-".repeat(8), "-".repeat(10));

            double sumaGlobal = 0;
            int aprobados = 0;

            for (Alumno a : alumnos) {
                pw.printf("%-20s %8d %10.2f%n",
                    a.getNombre(), a.getNumNotas(), a.getNotaMedia());
                sumaGlobal += a.getNotaMedia();
                if (a.getNotaMedia() >= 5.0) aprobados++;
            }

            pw.println();
            pw.println("-".repeat(50));
            pw.printf("Total alumnos: %d%n", alumnos.size());
            pw.printf("Aprobados: %d (%.1f%%)%n", aprobados,
                (double) aprobados / alumnos.size() * 100);
            pw.printf("Suspensos: %d%n", alumnos.size() - aprobados);
            pw.printf("Media global: %.2f%n", sumaGlobal / alumnos.size());

            System.out.println("Informe generado: " + ruta);
        } catch (IOException e) {
            System.out.println("Error generando informe: " + e.getMessage());
        }
    }
}

