    // === GUARDAR objetos en un fichero ===
    public static void guardarAlumnos(List<Alumno> alumnos, String ruta) {
        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(ruta))) {
            oos.writeObject(alumnos);
            System.out.println("Alumnos guardados en: " + ruta);
        } catch (IOException e) {
            System.out.println("Error guardando: " + e.getMessage());
        }
    }

    // === CARGAR objetos desde un fichero ===
    @SuppressWarnings("unchecked")
    public static List<Alumno> cargarAlumnos(String ruta) {
        try (ObjectInputStream ois = new ObjectInputStream(
                new FileInputStream(ruta))) {
            return (List<Alumno>) ois.readObject();
        } catch (FileNotFoundException e) {
            System.out.println("Fichero no encontrado, creando lista vacia");
            return new ArrayList<>();
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error cargando: " + e.getMessage());
            return new ArrayList<>();
        }
    }

    public static void main(String[] args) {
        // Crear alumnos
        List<Alumno> alumnos = new ArrayList<>();
        Alumno a1 = new Alumno("Ana", "ana@email.com");
        a1.addNota(8.5); a1.addNota(7.0);
        alumnos.add(a1);

        Alumno a2 = new Alumno("Carlos", "carlos@email.com");
        a2.addNota(6.0); a2.addNota(5.5);
        alumnos.add(a2);

        // Guardar
        guardarAlumnos(alumnos, "alumnos.dat");

        // Cargar
        List<Alumno> cargados = cargarAlumnos("alumnos.dat");
        System.out.println("\nAlumnos cargados: " + cargados.size());
        for (Alumno a : cargados) {
            System.out.println(a);
            // Token de sesion sera null (transient)
            System.out.println("  Token: " + a.getTokenSesion());
        }
    }
}

