import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class GestorPersistencia implements Serializable {
    private static final long serialVersionUID = 1L;

    private List<Alumno> alumnos;
    private List<Curso> cursos;
    private String fechaActualizacion;

    public GestorPersistencia() {
        this.alumnos = new ArrayList<>();
        this.cursos = new ArrayList<>();
        this.fechaActualizacion = "Nunca";
    }

    public void guardar(String ruta) throws IOException {
        // Crear backup
        File original = new File(ruta);
        if (original.exists()) {
            File backup = new File(ruta + ".bak");
            original.renameTo(backup);
        }

        this.fechaActualizacion = java.time.LocalDateTime.now().toString();
        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(ruta))) {
            oos.writeObject(this);
        }
    }

    public static GestorPersistencia cargar(String ruta) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(
                new FileInputStream(ruta))) {
            return (GestorPersistencia) ois.readObject();
        }
    }
}
